package com.lianxibu.site.domain.jobs;
import static org.junit.jupiter.api.Assertions.*;import java.time.Instant;import org.junit.jupiter.api.Test;
class CollectorNodeFactsTest {
 Instant at=Instant.parse("2026-01-01T00:10:00Z");
 CollectorNodeFacts.Heartbeat heartbeat(){return new CollectorNodeFacts.Heartbeat(1,3,at.minusSeconds(1),at,0,0,0,10,20,null);}
 @Test void completeOriginalHeartbeatRemainsDistinctFromMissingAndOldRevision(){var sample=heartbeat();var value=new CollectorNodeFacts.Evidence("fictional-node",2,true,at.minusSeconds(600),sample,0,at);assertEquals(1,value.heartbeat().nodeRevision());assertEquals(2,value.nodeRevision());assertEquals("CollectorNodeFacts[redacted]",value.toString());assertEquals("CollectorNodeHeartbeat[redacted]",sample.toString());var absent=new CollectorNodeFacts.Evidence("fictional-node",2,true,at.minusSeconds(600),null,1,at);assertNull(absent.heartbeat());assertEquals(1,absent.pendingServerClaims());}
 @Test void aCompleteEmptyQueueAndActualPendingOldestHaveExactSafeCounters(){var zero=heartbeat();assertNull(zero.oldestPendingAt());assertEquals(0,zero.pendingObservations());var pending=new CollectorNodeFacts.Heartbeat(1,1,at,at,1,0,0,9007199254740991L,0,at.minusSeconds(60));assertEquals(9007199254740991L,pending.outboxBytes());assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Heartbeat(1,1,at,at,1,0,0,0,0,null));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Heartbeat(1,1,at,at,0,0,0,0,0,at));}
 @Test void unsafeOrFutureOrUnprovenNodeIdentityAndReadCapacityAreRejected(){assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Evidence("fictional-node",0,true,at,null,0,at));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Evidence("fictional-node",1,true,at,heartbeat(),201,at));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Evidence("fictional-node",1,true,at.plusSeconds(1),null,0,at));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Evidence("fictional-node",1,true,at,heartbeat(),0,at.minusSeconds(1)));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Evidence("fictional-node",1,true,at,new CollectorNodeFacts.Heartbeat(2,1,at,at,0,0,0,0,0,null),0,at));for(String id:new String[]{"","x".repeat(65),"fictional\nnode","\uD800"})assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Evidence(id,1,true,at,null,0,at));}
 @Test void noPrecisionOrNegativeCounterBypassThroughDirectConstruction(){assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Heartbeat(1,1,at.plusNanos(1),at,0,0,0,0,0,null));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Heartbeat(1,1,at,at.minusSeconds(1),0,0,0,0,0,null));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Heartbeat(1,1,at,at,0,0,-1,0,0,null));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Heartbeat(1,1,at,at,0,0,0,9007199254740992L,0,null));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Heartbeat(1,1,at,at,1,0,0,0,0,at.plusSeconds(1)));}
 @Test void unavailableApiNeverCreatesHealthyDefaults(){CollectorNodeFacts.Api unavailable=id->null;assertNull(unavailable.read("fictional-node"));assertThrows(IllegalArgumentException.class,()->new CollectorNodeFacts.Evidence("fictional-node",1,true,null,null,0,at));}
}
